const droneBodyMat  = new THREE.MeshStandardMaterial({ color: 0x2b3441, metalness: 0.75, roughness: 0.3 });
const droneDarkMat  = new THREE.MeshStandardMaterial({ color: 0x141a23, metalness: 0.6, roughness: 0.45 });
const visorMat      = new THREE.MeshStandardMaterial({ color: 0x02141c, emissive: 0x2fd8ff, emissiveIntensity: 1.8 });
const rotorBladeMat = new THREE.MeshStandardMaterial({ color: 0x42505f, metalness: 0.6, roughness: 0.4, side: THREE.DoubleSide });
const rotorDiscMat  = new THREE.MeshBasicMaterial({ color: 0xbfe4ff, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });

function makeDrone(i) {
  const g = new THREE.Group();
  const hub = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.34, 1.35), droneBodyMat); g.add(hub);
  const belly = new THREE.Mesh(new THREE.BoxGeometry(0.72, 0.14, 0.95), droneDarkMat);
  belly.position.y = -0.23; g.add(belly);
  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.15, 0.06), visorMat);
  visor.position.set(0, 0.03, -0.7); g.add(visor);
  const rotors = [];
  for (let k = 0; k < 4; k++) {
    const a = Math.PI / 4 + k * Math.PI / 2;
    const dir = V3(Math.sin(a), 0, Math.cos(a));
    const arm = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.09, 0.9), droneDarkMat);
    arm.position.copy(dir).multiplyScalar(0.78);
    arm.rotation.y = a; g.add(arm);
    const motor = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.18, 0.2, 10), droneDarkMat);
    motor.position.copy(dir).multiplyScalar(1.28); motor.position.y = 0.12; g.add(motor);
    const rotor = new THREE.Group();
    rotor.position.copy(dir).multiplyScalar(1.28); rotor.position.y = 0.26;
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.6, 20), rotorDiscMat);
    disc.rotation.x = -Math.PI / 2; rotor.add(disc);
    for (let b2 = 0; b2 < 2; b2++) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(1.12, 0.02, 0.1), rotorBladeMat);
      blade.rotation.y = b2 * Math.PI / 2;
      rotor.add(blade);
    }
    g.add(rotor);
    rotors.push(rotor);
  }
  for (const sx of [-0.55, 0.55]) {
    const skid = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.06, 1.5), droneDarkMat);
    skid.position.set(sx, -0.45, 0); g.add(skid);
  }
  const amber = i % 2 === 1;
  const beaconMat = new THREE.MeshStandardMaterial({ color: 0x120607, emissive: amber ? 0xff9a1f : 0xff2a1f, emissiveIntensity: 1 });
  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 8), beaconMat);
  beacon.position.set(0, 0.3, 0); g.add(beacon);
  const bGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, color: amber ? 0xffaa55 : 0xff4433,
    transparent: true, opacity: 0.9, depthWrite: false, fog: false, blending: THREE.AdditiveBlending
  }));
  bGlow.scale.setScalar(1.4); bGlow.position.set(0, 0.3, 0); g.add(bGlow);
  const navL = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 6),
    new THREE.MeshStandardMaterial({ color: 0x021008, emissive: 0x37ff9e, emissiveIntensity: 2 }));
  navL.position.set(-1.3, 0.05, 0); g.add(navL);
  const navR = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 6),
    new THREE.MeshStandardMaterial({ color: 0x100404, emissive: 0xff4433, emissiveIntensity: 2 }));
  navR.position.set(1.3, 0.05, 0); g.add(navR);

  scene.add(g);
  return { g, rotors, beaconMat, bGlow, phase: i * 1.7, pos: new THREE.Vector3(), target: new THREE.Vector3(), yaw: 0, prev: new THREE.Vector3(), speed: 0 };
}

