/* ================= main loop ================= */
const clock = new THREE.Clock();
let elapsed = 0;
const cinePos = new THREE.Vector3();
const camPos = new THREE.Vector3();
const lookPt = new THREE.Vector3();
let lastT = 0;

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(0.05, clock.getDelta());
  elapsed += dt;
  const t = elapsed;

  /* --- drones --- */
  for (let i = 0; i < drones.length; i++) {
    const d = drones[i];
    const k = 1 - Math.exp(-2.4 * dt);
    d.prev.copy(d.pos);
    d.pos.lerp(d.target, k);
    const bob = Math.sin(t * 1.5 + d.phase) * 0.22 + Math.sin(t * 0.53 + d.phase * 2.1) * 0.1;
    d.g.position.set(d.pos.x, d.pos.y + bob, d.pos.z);

    const vx = d.target.x - d.pos.x;
    const vz = d.target.z - d.pos.z;
    const vy = d.target.y - d.pos.y;
    const spd = Math.hypot(vx, vz);

    let ty = 0;
    if (spd > 0.35) ty = Math.atan2(-vx, -vz);
    let dYaw = ty - d.yaw;
    while (dYaw > Math.PI) dYaw -= Math.PI * 2;
    while (dYaw < -Math.PI) dYaw += Math.PI * 2;
    d.yaw += dYaw * (1 - Math.exp(-2.5 * dt));
    d.g.rotation.y = d.yaw;
    d.g.rotation.z = clamp(dYaw * 0.09, -0.14, 0.14) * (1 - Math.exp(-3 * dt));
    d.g.rotation.x = clamp(vy * 0.25, -0.15, 0.15);

    for (const r of d.rotors) r.rotation.y += dt * (16 + 3 * Math.sin(t * 3 + d.phase));
    const p = Math.pow(0.5 + 0.5 * Math.sin(t * (i % 2 ? 2.2 : 2.8) + d.phase * 3), 3);
    d.beaconMat.emissiveIntensity = 0.25 + 2.8 * p;
    d.bGlow.scale.setScalar(1.0 + 1.8 * p);

    d.speed = d.pos.distanceTo(d.prev) / Math.max(dt, 1e-4);
  }

  /* --- warning lights --- */
  for (let i = 0; i < beacons.length; i++) {
    const b = beacons[i];
    const pulse = Math.pow(0.5 + 0.5 * Math.sin(t * 2.6 + b.phase), 3);
    b.mat.emissiveIntensity = 0.25 + 3.0 * pulse;
    b.glow.material.opacity = 0.25 + 0.6 * pulse;
    b.glow.scale.setScalar(3.5 + 3.5 * pulse);
    if (b.beam) b.beam.rotation.y = t * 1.1 + b.beamPhase;
  }
  beaconLights[0].intensity = 6 + 70 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.6), 3);
  beaconLights[1].intensity = 6 + 70 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.6 + 2.1), 3);
  for (let i = 0; i < barMats.length; i++) {
    const active = (Math.floor(t * 4) % 12) === (i % 12);
    barMats[i].emissiveIntensity = active ? 3.2 : 0.12;
  }

  /* --- emissive runway strips --- */
  for (let i = 0; i < dashMats.length; i++) {
    dashMats[i].emissiveIntensity = 0.7 + 1.8 * (0.5 + 0.5 * Math.sin(t * 3 - i * 0.55));
  }
  for (let i = 0; i < padDashMats.length; i++) {
    padDashMats[i].emissiveIntensity = 0.8 + 1.6 * (0.5 + 0.5 * Math.sin(t * 2 + i * 0.6));
  }
  padRing.rotation.y = t * 0.35;

  /* --- door glow, shafts, pool --- */
  portal.material.color.setHSL(0.58, 0.6, 0.55 + 0.12 * Math.sin(t * 0.8));
  shaftMat.opacity = 0.10 + 0.06 * (0.5 + 0.5 * Math.sin(t * 0.6));
  pool.material.opacity = 0.08 + 0.04 * (0.5 + 0.5 * Math.sin(t * 0.6 + 1));

  /* --- fog planes --- */
  fogMul = lerp(fogMul, fogOn ? 1 : 0, 1 - Math.exp(-3 * dt));
  scene.fog.density = lerp(scene.fog.density, fogOn ? 0.014 : 0.005, 1 - Math.exp(-3 * dt));
  for (const f of fogPlanes) {
    const vis = fogMul > 0.01;
    f.m.visible = vis;
    if (!vis) continue;
    f.m.material.opacity = f.base * fogMul * (0.75 + 0.25 * Math.sin(t * 0.35 + f.phase));
    f.m.position.x = f.x0 + Math.sin(t * 0.12 + f.phase) * 3 * f.drift;
  }

  /* --- dust --- */
  for (let i = 0; i < DUST; i++) {
    let y = dustPos[i * 3 + 1] + dustVel[i] * dt;
    if (y > 14) y = 0.2;
    dustPos[i * 3 + 1] = y;
    dustPos[i * 3] += Math.sin(t * 0.2 + i) * 0.002;
  }
  dustGeo.attributes.position.needsUpdate = true;

  /* --- camera --- */
  cineT = (cineT + dt / cineDur) % 1;
  cinePath.getPointAt(cineT, cinePos);
  cineLook.lerpVectors(new THREE.Vector3(), cineLook, 0); // no-op
  cineTarget(cineT);
  cineLook.x += Math.sin(t * 1.1) * 0.5;
  cineLook.y += Math.sin(t * 0.7 + 2) * 0.3;
  cinePos.x += Math.sin(t * 1.7) * 0.12;
  cinePos.y += Math.sin(t * 1.3 + 1) * 0.1;

  camBlend = clamp(camBlend + (cineOn ? dt / 2.2 : -dt / 2.2), 0, 1);
