  #status .cur { display:inline-block; width:7px; height:12px; background:#39ffb0; vertical-align:-1px; animation:blink 1.1s steps(1) infinite; }
  @keyframes blink { 50% { opacity:0; } }
  #panel { position:absolute; top:18px; right:22px; display:flex; flex-direction:column; gap:8px; pointer-events:auto; }
  #panel button { font:inherit; font-size:11px; letter-spacing:.22em; text-align:left; padding:9px 16px;
    color:#9fe8ff; background:rgba(6,16,26,.6); border:1px solid rgba(53,224,255,.35); cursor:pointer;
    backdrop-filter:blur(4px); transition:border-color .2s, box-shadow .2s, background .2s, color .2s; }
  #panel button:hover { border-color:var(--cyan); color:#e8faff; box-shadow:0 0 16px rgba(53,224,255,.35); }
  #panel button.on { background:rgba(53,224,255,.14); border-color:var(--cyan); color:#e8faff; }
  #panel .lbl { color:var(--dim); }
  #hint { position:absolute; right:22px; bottom:18px; text-align:right; font-size:10px;
    line-height:1.9; letter-spacing:.2em; color:var(--dim); }
  #hint b { color:#9fe8ff; font-weight:400; }
</style>
</head>
<body>
<div id="hud">
  <div class="vig"></div>
  <div class="scan"></div>
  <div id="title"><span class="t1">HANGAR&nbsp;20</span><span class="t2">AUTONOMOUS DRONE OPERATIONS BAY</span></div>
  <div id="status"></div>
  <div id="panel">
    <button id="bForm"><span class="lbl">FORMATION</span> :: <span id="vForm">WEDGE</span></button>
    <button id="bCine" class="on"><span class="lbl">CAMERA</span> :: <span id="vCine">CINEMATIC</span></button>
    <button id="bFog" class="on"><span class="lbl">ATMOS</span> :: <span id="vFog">FOG ON</span></button>
  </div>
  <div id="hint">
    <div><b>F</b> FORMATION &nbsp; <b>C</b> CAMERA &nbsp; <b>G</b> FOG</div>
    <div>DRAG — ORBIT &nbsp;·&nbsp; WHEEL — ZOOM</div>
  </div>
</div>

<script type="module">
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";

/* ================= helpers ================= */
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp  = (a, b, t) => a + (b - a) * t;
const sstep = (a, b, x) => { x = clamp((x - a) / (b - a), 0, 1); return x * x * (3 - 2 * x); };
const V3    = (x, y, z) => new THREE.Vector3(x, y, z);
const rand  = (a, b) => a + Math.random() * (b - a);

function canvasTex(size, draw, srgb = true) {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  draw(c.getContext("2d"), size);
  const t = new THREE.CanvasTexture(c);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/* ================= procedural textures ================= */
const glowTex = canvasTex(256, (g, s) => {
  const gr = g.createRadialGradient(s/2, s/2, 0, s/2, s/2, s/2);
  gr.addColorStop(0.00, "rgba(255,255,255,1)");
  gr.addColorStop(0.22, "rgba(255,255,255,0.55)");
  gr.addColorStop(0.55, "rgba(255,255,255,0.12)");
  gr.addColorStop(1.00, "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const fogTex = canvasTex(256, (g, s) => {
  const gr = g.createRadialGradient(s/2, s/2, 0, s/2, s/2, s/2);
  gr.addColorStop(0.0,  "rgba(255,255,255,0.85)");
  gr.addColorStop(0.5,  "rgba(255,255,255,0.32)");
  gr.addColorStop(1.0,  "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const shaftTex = canvasTex(64, (g, s) => {
  const gr = g.createLinearGradient(0, 0, 0, s);
  gr.addColorStop(0.00, "rgba(255,255,255,0.65)");
  gr.addColorStop(0.45, "rgba(255,255,255,0.22)");
  gr.addColorStop(1.00, "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const floorTex = canvasTex(512, (g, s) => {
  g.fillStyle = "#11161e"; g.fillRect(0, 0, s, s);
  g.strokeStyle = "rgba(70,90,110,0.35)"; g.lineWidth = 2;
  for (let i = 0; i <= s; i += 64) {
    g.beginPath(); g.moveTo(i, 0); g.lineTo(i, s); g.stroke();
    g.beginPath(); g.moveTo(0, i); g.lineTo(s, i); g.stroke();
  }
  g.strokeStyle = "rgba(95,125,155,0.5)"; g.lineWidth = 3;
  g.strokeRect(1.5, 1.5, s - 3, s - 3);
  for (let i = 0; i < 500; i++) {
    g.fillStyle = `rgba(255,255,255,${Math.random() * 0.04})`;
    g.fillRect(Math.random() * s, Math.random() * s, 2, 2);
  }
});
floorTex.wrapS = floorTex.wrapT = THREE.RepeatWrapping;
floorTex.repeat.set(4, 9);

const starsTex = canvasTex(1024, (g, s) => {
  g.fillStyle = "#020308"; g.fillRect(0, 0, s, s);
  let gr = g.createRadialGradient(s*0.35, s*0.55, 0, s*0.35, s*0.55, s*0.5);
  gr.addColorStop(0, "rgba(40,70,120,0.55)");
  gr.addColorStop(0.5, "rgba(30,40,80,0.25)");
  gr.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
  gr = g.createRadialGradient(s*0.7, s*0.35, 0, s*0.7, s*0.35, s*0.4);
  gr.addColorStop(0, "rgba(90,60,140,0.4)");
  gr.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 450; i++) {
    const x = Math.random()*s, y = Math.random()*s, r = Math.random()*1.4 + 0.3;
    g.fillStyle = `rgba(255,255,255,${0.25 + Math.random()*0.75})`;
    g.beginPath(); g.arc(x, y, r, 0, 7); g.fill();
  }
});

const portalTex = canvasTex(512, (g, s) => {
  g.fillStyle = "#01030a"; g.fillRect(0, 0, s, s);
  const gr = g.createRadialGradient(s/2, s/2, 0, s/2, s/2, s*0.62);
  gr.addColorStop(0,   "rgba(130,205,255,0.95)");
  gr.addColorStop(0.4, "rgba(60,120,200,0.5)");
  gr.addColorStop(1,   "rgba(8,16,34,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const signTex = canvasTex(1024, (g, s) => {
  g.fillStyle = "#0a141d"; g.fillRect(0, 0, s, s);
  g.strokeStyle = "rgba(53,224,255,0.8)"; g.lineWidth = 6;
  g.strokeRect(14, 14, s - 28, s - 28);
  g.textAlign = "center"; g.textBaseline = "middle";
  g.shadowColor = "rgba(53,224,255,0.9)"; g.shadowBlur = 28;
  g.fillStyle = "#bfeeff"; g.font = "700 130px ui-monospace, monospace";
  g.fillText("HANGAR 20", s/2, s/2 - 40);
  g.font = "400 46px ui-monospace, monospace"; g.fillStyle = "#4f9fc0";
  g.fillText("DRONE OPERATIONS BAY", s/2, s/2 + 60);
});

/* ================= renderer / scene ================= */
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x04070c);
scene.fog = new THREE.FogExp2(0x071018, 0.014);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 600);

const HANGAR = { halfW: 22, h: 16, zNear: 34, zFar: -58, zMid: -12 };

/* ================= hangar shell ================= */
const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(HANGAR.halfW * 2, HANGAR.zNear - HANGAR.zFar),
  new THREE.MeshStandardMaterial({ map: floorTex, color: 0xb9c2cf, metalness: 0.45, roughness: 0.55 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.set(0, 0, HANGAR.zMid);
scene.add(floor);

// runway deck + emissive edge strips + center dashes
const runway = new THREE.Mesh(
  new THREE.BoxGeometry(10.4, 0.08, HANGAR.zNear - HANGAR.zFar),
  new THREE.MeshStandardMaterial({ color: 0x0c1118, metalness: 0.6, roughness: 0.35 })
);
runway.position.set(0, 0.04, HANGAR.zMid);
scene.add(runway);

const edgeMat = new THREE.MeshStandardMaterial({ color: 0x02141a, emissive: 0x19d6ff, emissiveIntensity: 2.4, roughness: 0.4 });
for (const sx of [-1, 1]) {
  const e = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.1, HANGAR.zNear - HANGAR.zFar), edgeMat);
  e.position.set(sx * 5.2, 0.09, HANGAR.zMid);
  scene.add(e);
}
const dashMats = [];
for (let i = 0; i < 20; i++) {
  const m = new THREE.MeshStandardMaterial({ color: 0x1a1206, emissive: 0xffb347, emissiveIntensity: 2 });
  const d = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.08, 2.4), m);
  d.position.set(0, 0.09, 28 - i * 4.105);
  scene.add(d);
  dashMats.push(m);
}
// dock threshold bars
for (const sx of [-3.4, 3.4]) {
  const tb = new THREE.Mesh(new THREE.BoxGeometry(2, 0.08, 0.9),
    new THREE.MeshStandardMaterial({ color: 0x101418, emissive: 0xeaf6ff, emissiveIntensity: 1.6 }));
  tb.position.set(sx, 0.09, 31.5);
  scene.add(tb);
}

// pillars + beacons
const pillarMat = new THREE.MeshStandardMaterial({ color: 0x161d27, metalness: 0.5, roughness: 0.6 });
const baseMat   = new THREE.MeshStandardMaterial({ color: 0x10151d, metalness: 0.5, roughness: 0.6 });
const beacons = [];
const beaconLights = [];
for (const px of [-9, 9]) for (const pz of [28, 8, -12, -32, -52]) {
  const p = new THREE.Group();
  const col = new THREE.Mesh(new THREE.BoxGeometry(1.5, HANGAR.h, 1.5), pillarMat);
  col.position.y = HANGAR.h / 2; p.add(col);
  const base = new THREE.Mesh(new THREE.BoxGeometry(2.3, 0.3, 2.3), baseMat);
  base.position.y = 0.15; p.add(base);
  const amber = ((px < 0 ? 1 : 0) ^ (pz > 10 ? 1 : 0)) === 1;
  const bm = new THREE.MeshStandardMaterial({ color: 0x120607, emissive: amber ? 0xff9a1f : 0xff2a1f, emissiveIntensity: 1 });
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.42, 16, 12), bm);
  head.position.y = HANGAR.h + 0.35; p.add(head);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, color: amber ? 0xffaa55 : 0xff4433,
    transparent: true, opacity: 0.8, depthWrite: false, fog: false, blending: THREE.AdditiveBlending
  }));
  glow.scale.setScalar(5); glow.position.y = HANGAR.h + 0.35; p.add(glow);
  p.position.set(px, 0, pz);
  scene.add(p);
  beacons.push({ mat: bm, glow, phase: ((px + 10) * 7 + (pz + 60)) % 10, px, pz, rot: null });
}
// two beacons get real pulsing point lights
const plA = new THREE.PointLight(0xff2a1f, 30, 28, 2); plA.position.set(-9, 16.2, 28); scene.add(plA);
const plB = new THREE.PointLight(0xff2a1f, 30, 28, 2); plB.position.set(9, 16.2, -32); scene.add(plB);
beaconLights.push(plA, plB);
// rotating search beams on three beacons
function makeBeam(color, h) {
  const g = new THREE.Group();
  const geo = new THREE.PlaneGeometry(2.4, h);
  geo.translate(0, -h / 2, 0);
  const mat = new THREE.MeshBasicMaterial({
    map: shaftTex, color, transparent: true, opacity: 0.3,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, fog: false
  });
  for (let k = 0; k < 2; k++) {
    const m = new THREE.Mesh(geo, mat);
    m.rotation.y = k * Math.PI / 2;
    g.add(m);
  }
  return g;
}
for (const b of beacons) {
  if ((b.px === -9 && b.pz === 28) || (b.px === 9 && b.pz === 8) || (b.px === -9 && b.pz === -32)) {
    const beam = makeBeam(b.mat.emissive.getHex(), 8);
    beam.position.y = HANGAR.h + 0.5;
    b.g = b.g; // no-op guard
    // attach to pillar world position
    const holder = new THREE.Group();
    holder.position.set(b.px, 0, b.pz);
    holder.add(beam);
    scene.add(holder);
    b.beam = beam;
    b.beamPhase = rand(0, 6.28);
  }
}

// wall light bars (chase pattern)
const barMats = [];
for (const side of [-1, 1]) for (let i = 0; i < 12; i++) {
  const m = new THREE.MeshStandardMaterial({
    color: 0x06121a,
    emissive: i % 2 ? 0x19d6ff : 0xff2a1f,
    emissiveIntensity: 0.15
  });
  const bar = new THREE.Mesh(new THREE.PlaneGeometry(0.9, 0.22), m);
  bar.rotation.y = side * Math.PI / 2;
  bar.position.set(side * (HANGAR.halfW - 0.06), 9.5, 28 - i * 7.4);
  scene.add(bar);
  barMats.push(m);
}

// ceiling + trusses + light strips
const ceiling = new THREE.Mesh(
  new THREE.BoxGeometry(HANGAR.halfW * 2, 0.4, HANGAR.zNear - HANGAR.zFar),
  new THREE.MeshStandardMaterial({ color: 0x131a23, metalness: 0.4, roughness: 0.7 })
);
ceiling.position.set(0, HANGAR.h + 0.2, HANGAR.zMid);
scene.add(ceiling);
const trussMat = new THREE.MeshStandardMaterial({ color: 0x1f2937, metalness: 0.6, roughness: 0.5 });
for (const z of [30, 10, -10, -30, -50]) {
  const tr = new THREE.Mesh(new THREE.BoxGeometry(HANGAR.halfW * 2, 0.5, 0.5), trussMat);
  tr.position.set(0, HANGAR.h - 0.3, z); scene.add(tr);
}
const stripMat = new THREE.MeshStandardMaterial({ color: 0x0a141c, emissive: 0xcfeeff, emissiveIntensity: 1.6 });
for (const z of [24, 4, -16, -36]) {
  const st = new THREE.Mesh(new THREE.BoxGeometry(28, 0.1, 0.7), stripMat);
  st.position.set(0, HANGAR.h - 0.6, z); scene.add(st);
}

// side + near walls, sign
const wallMat = new THREE.MeshStandardMaterial({ color: 0x151c26, metalness: 0.35, roughness: 0.75 });
for (const side of [-1, 1]) {
  const w = new THREE.Mesh(new THREE.BoxGeometry(0.5, HANGAR.h, HANGAR.zNear - HANGAR.zFar), wallMat);
  w.position.set(side * HANGAR.halfW, HANGAR.h / 2, HANGAR.zMid); scene.add(w);
}
const wN = new THREE.Mesh(new THREE.BoxGeometry(HANGAR.halfW * 2, HANGAR.h, 0.5), wallMat);
wN.position.set(0, HANGAR.h / 2, HANGAR.zNear); scene.add(wN);
const sign = new THREE.Mesh(new THREE.PlaneGeometry(12, 3), new THREE.MeshBasicMaterial({ map: signTex, fog: false }));
sign.position.set(0, 10, HANGAR.zNear - 0.31);
sign.rotation.y = Math.PI;
scene.add(sign);

// far end: hangar door + glowing portal to space
const dwL = new THREE.Mesh(new THREE.BoxGeometry(13, HANGAR.h, 0.5), wallMat);
dwL.position.set(-15.5, HANGAR.h / 2, HANGAR.zFar); scene.add(dwL);
const dwR = new THREE.Mesh(new THREE.BoxGeometry(13, HANGAR.h, 0.5), wallMat);
dwR.position.set(15.5, HANGAR.h / 2, HANGAR.zFar); scene.add(dwR);
const dwT = new THREE.Mesh(new THREE.BoxGeometry(18, HANGAR.h - 12, 0.5), wallMat);
dwT.position.set(0, 12 + (HANGAR.h - 12) / 2, HANGAR.zFar); scene.add(dwT);
const trimMat = new THREE.MeshStandardMaterial({ color: 0x0d1219, metalness: 0.7, roughness: 0.4, emissive: 0x0a2a38, emissiveIntensity: 0.6 });
for (const sx of [-9.2, 9.2]) {
  const j = new THREE.Mesh(new THREE.BoxGeometry(0.6, 12.4, 0.8), trimMat);
  j.position.set(sx, 6.2, HANGAR.zFar); scene.add(j);
}
const lintel = new THREE.Mesh(new THREE.BoxGeometry(19, 0.6, 0.8), trimMat);
lintel.position.set(0, 12.3, HANGAR.zFar); scene.add(lintel);

const portal = new THREE.Mesh(new THREE.PlaneGeometry(18, 12), new THREE.MeshBasicMaterial({ map: portalTex, fog: false }));
portal.position.set(0, 6, HANGAR.zFar - 0.2); scene.add(portal);
const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(340, 170), new THREE.MeshBasicMaterial({ map: starsTex, fog: false }));
backdrop.position.set(0, 45, -160); scene.add(backdrop);
const planet = new THREE.Mesh(new THREE.SphereGeometry(7, 24, 18), new THREE.MeshBasicMaterial({ color: 0x3a5f8f, fog: false }));
planet.position.set(34, 42, -150); scene.add(planet);

// volumetric-style door light shafts (crossed gradient quads) + floor pool
function shaftQuad(wTop, yTop, zTop, wBot, yBot, zBot) {
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(new Float32Array([
    -wTop, yTop, zTop,  wTop, yTop, zTop,
    -wBot, yBot, zBot,  wBot, yBot, zBot
  ]), 3));
  g.setAttribute("uv", new THREE.BufferAttribute(new Float32Array([0, 1, 1, 1, 0, 0, 1, 0]), 2));
  g.setIndex([0, 2, 1, 1, 2, 3]);
  return g;
}
const shaftMat = new THREE.MeshBasicMaterial({
  map: shaftTex, color: 0x7fc4ff, transparent: true, opacity: 0.14,
  blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, fog: false
});
for (let k = 0; k < 2; k++) {
  const q = new THREE.Mesh(shaftQuad(8, 11.5, HANGAR.zFar, 24, 0.06, HANGAR.zFar + 28), shaftMat);
  q.rotation.y = k * Math.PI / 2;
  q.renderOrder = 4;
  scene.add(q);
}
const pool = new THREE.Mesh(new THREE.PlaneGeometry(30, 34), new THREE.MeshBasicMaterial({
  map: glowTex, color: 0x4d9fd8, transparent: true, opacity: 0.1,
  blending: THREE.AdditiveBlending, depthWrite: false, fog: false
}));
pool.rotation.x = -Math.PI / 2;
pool.position.set(0, 0.05, -40);
pool.renderOrder = 3;
scene.add(pool);

// dock ring (rotating emissive dashes)
const padRing = new THREE.Group();
const padDashMats = [];
for (let i = 0; i < 20; i++) {
  const m = new THREE.MeshStandardMaterial({ color: 0x04140e, emissive: 0x37ffb0, emissiveIntensity: 1.5 });
  const d = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.06, 0.18), m);
  const a = (i / 20) * Math.PI * 2;
  d.position.set(Math.cos(a) * 5.2, 0.09, Math.sin(a) * 5.2);
  d.rotation.y = -a;
  padRing.add(d);
  padDashMats.push(m);
}
const padCenter = new THREE.Mesh(new THREE.CircleGeometry(1.4, 32),
  new THREE.MeshStandardMaterial({ color: 0x04140e, emissive: 0x37ffb0, emissiveIntensity: 1.2 }));
padCenter.rotation.x = -Math.PI / 2;
padCenter.position.y = 0.07;
padRing.add(padCenter);
padRing.position.set(0, 0, 28);
scene.add(padRing);

// cargo props
const crateMat = new THREE.MeshStandardMaterial({ color: 0x232c38, metalness: 0.5, roughness: 0.55 });
const crateGlow = new THREE.MeshStandardMaterial({ color: 0x061218, emissive: 0x19d6ff, emissiveIntensity: 0.9 });
function crate(x, z, s, ry) {
  const g = new THREE.Group();
  const b = new THREE.Mesh(new THREE.BoxGeometry(s, s * 0.8, s), crateMat);
  b.position.y = s * 0.4; g.add(b);
  const strip = new THREE.Mesh(new THREE.BoxGeometry(s * 1.01, s * 0.12, s * 0.35), crateGlow);
  strip.position.y = s * 0.5; g.add(strip);
  g.position.set(x, 0, z); g.rotation.y = ry;
  scene.add(g);
}
crate(16, 24, 2.2, 0.4); crate(17.5, 21, 1.6, -0.2); crate(15.5, 26.5, 1.4, 0.9);
crate(-16.5, -18, 2.0, 0.7); crate(-15, -21, 1.5, 0.1);
const tank = new THREE.Mesh(new THREE.CylinderGeometry(2, 2, 5, 20),
  new THREE.MeshStandardMaterial({ color: 0x2a3542, metalness: 0.7, roughness: 0.35 }));
tank.position.set(17.5, 2.5, -8); scene.add(tank);
const tankBand = new THREE.Mesh(new THREE.CylinderGeometry(2.03, 2.03, 0.4, 20), crateGlow);
tankBand.position.set(17.5, 3.2, -8); scene.add(tankBand);

/* ================= lights ================= */
scene.add(new THREE.HemisphereLight(0x44607a, 0x0a0e14, 0.55));
const keyLight  = new THREE.PointLight(0xcfe8ff, 140, 60, 2); keyLight.position.set(0, 13.5, -6); scene.add(keyLight);
const doorLight = new THREE.PointLight(0x8fc8ff, 220, 90, 2); doorLight.position.set(0, 7, -50); scene.add(doorLight);
const formLight = new THREE.PointLight(0x22d3ee, 50, 30, 2);  formLight.position.set(0, 5.5, 6); scene.add(formLight);

/* ================= volumetric-style fog planes ================= */
const fogPlanes = [];
const fogDefs = [
  [  0, 0.55,  24, 34, 0.07],
  [  2, 0.85,  12, 30, 0.10],
  [ -2, 0.50,   0, 36, 0.09],
  [  3, 0.75, -12, 30, 0.11],
  [ -3, 0.95, -24, 34, 0.10],
  [  0, 0.60, -38, 38, 0.13],
  [  1, 0.45, -50, 42, 0.15],
];
for (const [x, y, z, s, o] of fogDefs) {
  const m = new THREE.Mesh(
    new THREE.PlaneGeometry(s, s),
    new THREE.MeshBasicMaterial({ map: fogTex, color: 0x7fb2d8, transparent: true, opacity: o, depthWrite: false, side: THREE.DoubleSide, fog: false })
  );
  m.rotation.x = -Math.PI / 2; m.position.set(x, y, z); m.renderOrder = 6;
  scene.add(m);
  fogPlanes.push({ m, base: o, x0: x, phase: rand(0, 6.28), drift: rand(0.3, 0.9) * (Math.random() < 0.5 ? -1 : 1) });
}
for (const [x, y, z, s, o] of [[0, 0.35, 18, 40, 0.05], [0, 0.3, -20, 44, 0.06], [0, 0.3, -46, 48, 0.07]]) {
  const m = new THREE.Mesh(
    new THREE.PlaneGeometry(s, s),
    new THREE.MeshBasicMaterial({ map: fogTex, color: 0x1d4a6e, transparent: true, opacity: o, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, fog: false })
  );
  m.rotation.x = -Math.PI / 2; m.position.set(x, y, z); m.renderOrder = 7;
  scene.add(m);
  fogPlanes.push({ m, base: o, x0: x, phase: rand(0, 6.28), drift: rand(0.3, 0.9) });
}

// drifting dust motes
const DUST = 220;
const dustPos = new Float32Array(DUST * 3);
const dustVel = new Float32Array(DUST);
for (let i = 0; i < DUST; i++) {
  dustPos[i * 3] = rand(-20, 20);
  dustPos[i * 3 + 1] = rand(0.2, 14);
  dustPos[i * 3 + 2] = rand(-55, 32);
  dustVel[i] = rand(0.05, 0.2);
}
const dustGeo = new THREE.BufferGeometry();
dustGeo.setAttribute("position", new THREE.BufferAttribute(dustPos, 3));
const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
  map: glowTex, color: 0x7fb4e0, size: 0.16, transparent: true, opacity: 0.4,
  depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
}));
scene.add(dust);

/* ================= drones ================= */
const droneBodyMat  = new THREE.MeshStandardMaterial({ color: 0x2b3441, metalness: 0.75, roughness: 0.3 });
const droneDarkMat  = new THREE.MeshStandardMaterial({ color: 0x141a23, metalness: 0.6, roughness: 0.45 });
const visorMat      = new THREE.MeshStandardMaterial({ color: 0x02141c, emissive: 0x2fd8ff, emissiveIntensity: 1.8 });
const rotorBladeMat = new THREE.MeshStandardMaterial({ color: 0x42505f, metalness: 0.6, roughness: 0.4, side: THREE.DoubleSide });
const rotorDiscMat  = new THREE.MeshBasicMaterial({ color: 0xbfe4ff, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });

function makeDrone(i) {
  const g = new THREE.Group();
  const hub = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.34, 1.35), droneBodyMat); g.add(hub);
  const belly = new THREE.Mesh(new THREE.BoxGeometry(0.72, 0.14, 0.95), droneDarkMat);
  belly.position.y = -0.23; g.add(belly);
  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.15, 0.06), visorMat);
  visor.position.set(0, 0.03, -0.7); g.add(visor);
  const rotors = [];
  for (let k = 0; k < 4; k++) {
    const a = Math.PI / 4 + k * Math.PI / 2;
    const dir = V3(Math.sin(a), 0, Math.cos(a));
    const arm = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.09, 0.9), droneDarkMat);
    arm.position.copy(dir).multiplyScalar(0.78);
    arm.rotation.y = a; g.add(arm);
    const motor = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.18, 0.2, 10), droneDarkMat);
    motor.position.copy(dir).multiplyScalar(1.28); motor.position.y = 0.12; g.add(motor);
    const rotor = new THREE.Group();
    rotor.position.copy(dir).multiplyScalar(1.28); rotor.position.y = 0.26;
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.6, 20), rotorDiscMat);
    disc.rotation.x = -Math.PI / 2; rotor.add(disc);
    for (let b2 = 0; b2 < 2; b2++) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(1.12, 0.02, 0.1), rotorBladeMat);
      blade.rotation.y = b2 * Math.PI / 2;
      rotor.add(blade);
    }
    g.add(rotor);
    rotors.push(rotor);
  }
  for (const sx of [-0.55, 0.55]) {
    const skid = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.06, 1.5), droneDarkMat);
    skid.position.set(sx, -0.45, 0); g.add(skid);
  }
  const amber = i % 2 === 1;
  const beaconMat = new THREE.MeshStandardMaterial({ color: 0x120607, emissive: amber ? 0xff9a1f : 0xff2a1f, emissiveIntensity: 1 });
  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 8), beaconMat);
  beacon.position.set(0, 0.3, 0); g.add(beacon);
  const bGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTex, color: amber ? 0xffaa55 : 0xff4433,
    transparent: true, opacity: 0.9, depthWrite: false, fog: false, blending: THREE.AdditiveBlending
  }));
  bGlow.scale.setScalar(1.4); bGlow.position.set(0, 0.3, 0); g.add(bGlow);
  const navL = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 6),
    new THREE.MeshStandardMaterial({ color: 0x021008, emissive: 0x37ff9e, emissiveIntensity: 2 }));
  navL.position.set(-1.3, 0.05, 0); g.add(navL);
  const navR = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 6),
    new THREE.MeshStandardMaterial({ color: 0x100404, emissive: 0xff4433, emissiveIntensity: 2 }));
  navR.position.set(1.3, 0.05, 0); g.add(navR);

  scene.add(g);
  return { g, rotors, beaconMat, bGlow, phase: i * 1.7, pos: new THREE.Vector3(), target: new THREE.Vector3(), yaw: 0, prev: new THREE.Vector3(), speed: 0 };
}

const drones = [];
for (let i = 0; i < 6; i++) drones.push(makeDrone(i));

// formations: [ox, oy, oz] offsets from center, center (0, 3.4, 6)
const FORM_CENTER = V3(0, 3.4, 6);
const FORMS = {
  WEDGE: [[0, 0, 0], [-5, 0.2, 7], [5, 0.2, 7], [-10, 0.4, 14], [10, 0.4, 14], [0, 0.6, 21]],
  GRID:  [[-7, 0, -3], [0, 0, -3], [7, 0, -3], [-7, 1, 5], [0, 1, 5], [7, 1, 5]]
};
// start parked on the dock pad, then fly out
const DOCK = [[0, 1.2, 28], [-3.5, 1.1, 26], [3.5, 1.1, 26], [-6, 1.0, 23], [6, 1.0, 23], [0, 1.0, 21.5]];
let formation = "WEDGE";
function applyFormation(name) {
  formation = name;
  const off = FORMS[name];
  for (let i = 0; i < drones.length; i++) {
    drones[i].target.set(FORM_CENTER.x + off[i][0], FORM_CENTER.y + off[i][1], FORM_CENTER.z + off[i][2]);
  }
  vForm.textContent = name;
}
for (let i = 0; i < drones.length; i++) {
  drones[i].pos.set(DOCK[i][0], DOCK[i][1], DOCK[i][2]);
  drones[i].prev.copy(drones[i].pos);
  drones[i].g.position.copy(drones[i].pos);
}
applyFormation("WEDGE");

/* ================= cinematic camera ================= */
const cinePath = new THREE.CatmullRomCurve3([
  V3( 13, 2.4,  30),
  V3(  2, 1.7,  20),
  V3( -9, 2.6,  10),
  V3(  0.8, 2.4, 3.0),
  V3( 10, 6.5, -12),
  V3(  0, 13, -24),
  V3(-12, 6, -36),
  V3( -3, 3.2, -50),
  V3(  6, 7, -44),
  V3( 12, 4, -24)
], true, "centripetal", 0.5);

const cineDur = 48;   // seconds per loop
let cineT = 0;
let cineOn = true;
let camBlend = 0;

const tgtA = V3(0, 2.5, 14);    // runway / lead drone
const tgtB = V3(0, 3.6, 6);     // formation center
const tgtC = V3(0, 7, -58);     // hangar door
const cineLook = new THREE.Vector3();
function cineTarget(t) {
  if (t < 0.4)          cineLook.lerpVectors(tgtA, tgtB, sstep(0, 0.4, t));
  else if (t < 0.75)    cineLook.lerpVectors(tgtB, tgtC, sstep(0.4, 0.75, t));
  else if (t < 0.85)    cineLook.lerpVectors(tgtC, tgtB, sstep(0.75, 0.85, t));
  else                  cineLook.lerpVectors(tgtB, tgtA, sstep(0.85, 1, t));
}

// free-orbit view
const free = { theta: 0.55, phi: 1.15, r: 34, tTheta: 0.55, tPhi: 1.15, tR: 34 };
const FREE_LOOK = V3(0, 3.2, 2);
const freePos = new THREE.Vector3();
const freeLook = new THREE.Vector3();

/* ================= input ================= */
const el = renderer.domElement;
let dragging = false, lx = 0, ly = 0;
el.addEventListener("pointerdown", (e) => {
  dragging = true; lx = e.clientX; ly = e.clientY;
  el.setPointerCapture(e.pointerId);
});
el.addEventListener("pointermove", (e) => {
  if (!dragging) return;
  free.tTheta -= (e.clientX - lx) * 0.005;
  free.tPhi = clamp(free.tPhi - (e.clientY - ly) * 0.004, 0.18, 1.52);
  lx = e.clientX; ly = e.clientY;
});
el.addEventListener("pointerup", () => { dragging = false; });
el.addEventListener("wheel", (e) => {
  e.preventDefault();
  free.tR = clamp(free.tR * (1 + e.deltaY * 0.001), 8, 70);
}, { passive: false });

const bForm = document.getElementById("bForm");
const bCine = document.getElementById("bCine");
const bFog  = document.getElementById("bFog");
const vCine = document.getElementById("vCine");
const vFog  = document.getElementById("vFog");
const vForm = document.getElementById("vForm");

let fogOn = true;
let fogMul = 1;

function toggleFormation() { applyFormation(formation === "WEDGE" ? "GRID" : "WEDGE"); }
function toggleCine() {
  cineOn = !cineOn;
  bCine.classList.toggle("on", cineOn);
  vCine.textContent = cineOn ? "CINEMATIC" : "FREE ORBIT";
}
function toggleFog() {
  fogOn = !fogOn;
  bFog.classList.toggle("on", fogOn);
  vFog.textContent = fogOn ? "FOG ON" : "FOG OFF";
}
bForm.addEventListener("click", toggleFormation);
bCine.addEventListener("click", toggleCine);
bFog.addEventListener("click", toggleFog);
window.addEventListener("keydown", (e) => {
  const k = e.key.toLowerCase();
  if (k === "f") toggleFormation();
  else if (k === "c") toggleCine();
  else if (k === "g") toggleFog();
});

window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ================= HUD telemetry ================= */
const statusEl = document.getElementById("status");
let hudClock = 0;
function updateHUD(t, dt) {
  hudClock += dt;
  if (hudClock < 0.2) return;
  hudClock = 0;
  const lead = drones[0];
  const mm = String(Math.floor(t / 60)).padStart(2, "0");
  const ss = String(Math.floor(t % 60)).padStart(2, "0");
  statusEl.innerHTML =
    `<span class="g">SYS</span> ........ T+${mm}:${ss}  AIR CYCLE <span class="g">NOMINAL</span>\n` +
    `<span class="c">DRONES</span> ..... 06/06 AIRBORNE  ALT ${lead.g.position.y.toFixed(1)}m  SPD ${lead.speed.toFixed(1)}m/s\n` +
    `<span class="c">FORMATION</span> .. <span class="${formation === "WEDGE" ? "c" : "y"}">${formation}</span>\n` +
    `<span class="c">CAMERA</span> ..... <span class="${cineOn ? "r" : "c"}">${cineOn ? "CINEMATIC PATH" : "FREE ORBIT"}</span>\n` +
    `<span class="c">ATMOS</span> ...... ${fogOn ? '<span class="y">FOG LAYER ACTIVE</span>' : "CLEAR"} <span class="cur"></span>`;
}

/* ================= main loop ================= */
const clock = new THREE.Clock();
let elapsed = 0;
const cinePos = new THREE.Vector3();
const camPos = new THREE.Vector3();
const lookPt = new THREE.Vector3();
let lastT = 0;

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(0.05, clock.getDelta());
  elapsed += dt;
  const t = elapsed;

  /* --- drones --- */
  for (let i = 0; i < drones.length; i++) {
    const d = drones[i];
    const k = 1 - Math.exp(-2.4 * dt);
    d.prev.copy(d.pos);
    d.pos.lerp(d.target, k);
    const bob = Math.sin(t * 1.5 + d.phase) * 0.22 + Math.sin(t * 0.53 + d.phase * 2.1) * 0.1;
    d.g.position.set(d.pos.x, d.pos.y + bob, d.pos.z);

    const vx = d.target.x - d.pos.x;
    const vz = d.target.z - d.pos.z;
    const vy = d.target.y - d.pos.y;
    const spd = Math.hypot(vx, vz);

    let ty = 0;
    if (spd > 0.35) ty = Math.atan2(-vx, -vz);
    let dYaw = ty - d.yaw;
    while (dYaw > Math.PI) dYaw -= Math.PI * 2;
    while (dYaw < -Math.PI) dYaw += Math.PI * 2;
    d.yaw += dYaw * (1 - Math.exp(-2.5 * dt));
    d.g.rotation.y = d.yaw;
    d.g.rotation.z = clamp(dYaw * 0.09, -0.14, 0.14) * (1 - Math.exp(-3 * dt));
    d.g.rotation.x = clamp(vy * 0.25, -0.15, 0.15);

    for (const r of d.rotors) r.rotation.y += dt * (16 + 3 * Math.sin(t * 3 + d.phase));
    const p = Math.pow(0.5 + 0.5 * Math.sin(t * (i % 2 ? 2.2 : 2.8) + d.phase * 3), 3);
    d.beaconMat.emissiveIntensity = 0.25 + 2.8 * p;
    d.bGlow.scale.setScalar(1.0 + 1.8 * p);

    d.speed = d.pos.distanceTo(d.prev) / Math.max(dt, 1e-4);
  }

  /* --- warning lights --- */
  for (let i = 0; i < beacons.length; i++) {
    const b = beacons[i];
    const pulse = Math.pow(0.5 + 0.5 * Math.sin(t * 2.6 + b.phase), 3);
    b.mat.emissiveIntensity = 0.25 + 3.0 * pulse;
    b.glow.material.opacity = 0.25 + 0.6 * pulse;
    b.glow.scale.setScalar(3.5 + 3.5 * pulse);
    if (b.beam) b.beam.rotation.y = t * 1.1 + b.beamPhase;
  }
  beaconLights[0].intensity = 6 + 70 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.6), 3);
  beaconLights[1].intensity = 6 + 70 * Math.pow(0.5 + 0.5 * Math.sin(t * 2.6 + 2.1), 3);
  for (let i = 0; i < barMats.length; i++) {
    const active = (Math.floor(t * 4) % 12) === (i % 12);
    barMats[i].emissiveIntensity = active ? 3.2 : 0.12;
  }

  /* --- emissive runway strips --- */
  for (let i = 0; i < dashMats.length; i++) {
    dashMats[i].emissiveIntensity = 0.7 + 1.8 * (0.5 + 0.5 * Math.sin(t * 3 - i * 0.55));
  }
  for (let i = 0; i < padDashMats.length; i++) {
    padDashMats[i].emissiveIntensity = 0.8 + 1.6 * (0.5 + 0.5 * Math.sin(t * 2 + i * 0.6));
  }
  padRing.rotation.y = t * 0.35;

  /* --- door glow, shafts, pool --- */
  portal.material.color.setHSL(0.58, 0.6, 0.55 + 0.12 * Math.sin(t * 0.8));
  shaftMat.opacity = 0.10 + 0.06 * (0.5 + 0.5 * Math.sin(t * 0.6));
  pool.material.opacity = 0.08 + 0.04 * (0.5 + 0.5 * Math.sin(t * 0.6 + 1));

  /* --- fog planes --- */
  fogMul = lerp(fogMul, fogOn ? 1 : 0, 1 - Math.exp(-3 * dt));
  scene.fog.density = lerp(scene.fog.density, fogOn ? 0.014 : 0.005, 1 - Math.exp(-3 * dt));
  for (const f of fogPlanes) {
    const vis = fogMul > 0.01;
    f.m.visible = vis;
    if (!vis) continue;
    f.m.material.opacity = f.base * fogMul * (0.75 + 0.25 * Math.sin(t * 0.35 + f.phase));
    f.m.position.x = f.x0 + Math.sin(t * 0.12 + f.phase) * 3 * f.drift;
  }

  /* --- dust --- */
  for (let i = 0; i < DUST; i++) {
    let y = dustPos[i * 3 + 1] + dustVel[i] * dt;
    if (y > 14) y = 0.2;
    dustPos[i * 3 + 1] = y;
    dustPos[i * 3] += Math.sin(t * 0.2 + i) * 0.002;
  }
  dustGeo.attributes.position.needsUpdate = true;

  /* --- camera --- */
  cineT = (cineT + dt / cineDur) % 1;
  cinePath.getPointAt(cineT, cinePos);
  cineLook.lerpVectors(new THREE.Vector3(), cineLook, 0); // no-op
  cineTarget(cineT);
  cineLook.x += Math.sin(t * 1.1) * 0.5;
  cineLook.y += Math.sin(t * 0.7 + 2) * 0.3;
  cinePos.x += Math.sin(t * 1.7) * 0.12;
  cinePos.y += Math.sin(t * 1.3 + 1) * 0.1;

  camBlend = clamp(camBlend + (cineOn ? dt / 2.2 : -dt / 2.2), 0, 1);
  const b = camBlend * camBlend * (3 - 2 * camBlend);

  free.theta = lerp(free.theta, free.tTheta + (dragging ? 0 : dt * 0.04), 1 - Math.exp(-6 * dt));
  free.phi = lerp(free.phi, free.tPhi, 1 - Math.exp(-6 * dt));
  free.r = lerp(free.r, free.tR, 1 - Math.exp(-4 * dt));
  freePos.setFromSphericalCoords(free.r, free.phi, free.theta).add(FREE_LOOK);
  freeLook.copy(FREE_LOOK);

  camPos.lerpVectors(freePos, cinePos, b);
  lookPt.lerpVectors(freeLook, cineLook, b);
  camera.position.copy(camPos);
  camera.lookAt(lookPt);

  updateHUD(t, dt);
  renderer.render(scene, camera);
}
lastT = 0;
frame();
</script>
</body>
</html>
