  gr.addColorStop(0.00, "rgba(255,255,255,1)");
  gr.addColorStop(0.22, "rgba(255,255,255,0.55)");
  gr.addColorStop(0.55, "rgba(255,255,255,0.12)");
  gr.addColorStop(1.00, "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const fogTex = canvasTex(256, (g, s) => {
  const gr = g.createRadialGradient(s/2, s/2, 0, s/2, s/2, s/2);
  gr.addColorStop(0.0,  "rgba(255,255,255,0.85)");
  gr.addColorStop(0.5,  "rgba(255,255,255,0.32)");
  gr.addColorStop(1.0,  "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const shaftTex = canvasTex(64, (g, s) => {
  const gr = g.createLinearGradient(0, 0, 0, s);
  gr.addColorStop(0.00, "rgba(255,255,255,0.65)");
  gr.addColorStop(0.45, "rgba(255,255,255,0.22)");
  gr.addColorStop(1.00, "rgba(255,255,255,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const floorTex = canvasTex(512, (g, s) => {
  g.fillStyle = "#11161e"; g.fillRect(0, 0, s, s);
  g.strokeStyle = "rgba(70,90,110,0.35)"; g.lineWidth = 2;
  for (let i = 0; i <= s; i += 64) {
    g.beginPath(); g.moveTo(i, 0); g.lineTo(i, s); g.stroke();
    g.beginPath(); g.moveTo(0, i); g.lineTo(s, i); g.stroke();
  }
  g.strokeStyle = "rgba(95,125,155,0.5)"; g.lineWidth = 3;
  g.strokeRect(1.5, 1.5, s - 3, s - 3);
  for (let i = 0; i < 500; i++) {
    g.fillStyle = \`rgba(255,255,255,\${Math.random() * 0.04})\`;
    g.fillRect(Math.random() * s, Math.random() * s, 2, 2);
  }
});
floorTex.wrapS = floorTex.wrapT = THREE.RepeatWrapping;
floorTex.repeat.set(4, 9);

const starsTex = canvasTex(1024, (g, s) => {
  g.fillStyle = "#020308"; g.fillRect(0, 0, s, s);
  let gr = g.createRadialGradient(s*0.35, s*0.55, 0, s*0.35, s*0.55, s*0.5);
  gr.addColorStop(0, "rgba(40,70,120,0.55)");
  gr.addColorStop(0.5, "rgba(30,40,80,0.25)");
  gr.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
  gr = g.createRadialGradient(s*0.7, s*0.35, 0, s*0.7, s*0.35, s*0.4);
  gr.addColorStop(0, "rgba(90,60,140,0.4)");
  gr.addColorStop(1, "rgba(0,0,0,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
  for (let i = 0; i < 450; i++) {
    const x = Math.random()*s, y = Math.random()*s, r = Math.random()*1.4 + 0.3;
    g.fillStyle = \`rgba(255,255,255,\${0.25 + Math.random()*0.75})\`;
    g.beginPath(); g.arc(x, y, r, 0, 7); g.fill();
  }
});

const portalTex = canvasTex(512, (g, s) => {
  g.fillStyle = "#01030a"; g.fillRect(0, 0, s, s);
  const gr = g.createRadialGradient(s/2, s/2, 0, s/2, s/2, s*0.62);
  gr.addColorStop(0,   "rgba(130,205,255,0.95)");
  gr.addColorStop(0.4, "rgba(60,120,200,0.5)");
  gr.addColorStop(1,   "rgba(8,16,34,0)");
  g.fillStyle = gr; g.fillRect(0, 0, s, s);
});

const signTex = canvasTex(1024, (g, s) => {
  g.fillStyle = "#0a141d"; g.fillRect(0, 0, s, s);
