Probe script:
```html
<script>
(function(){
  function grab(id){ const e = document.getElementById(id); return e ? e.innerText : null; }
  setTimeout(function(){
    try {
      let info = { ok: true };
      const cv = document.querySelector('canvas');
      info.canvas = cv ? { w: cv.width, h: cv.height } : null;
      const r = window.__renderer;
      if (r) {
        const gl = r.getContext();
        const dbg = gl.getExtension('WEBGL_debug_renderer_info');
        info.gl = {
          version: gl.getParameter(gl.VERSION),
          vendor: dbg ? gl.getParameter(dbg.UNMASKED_VENDOR_WEBGL) : null,
          renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : null,
          isLost: gl.isContextLost(),
          programs: r.info.programs.active,
          calls: r.info.render.calls,
          points: r.info.render.points,
          tris: r.info.render.triangles
        };
        info.cam = { pos: r.camera.position.toArray(), t: r.info.render.frame };
      }
      info.hud = {
        title: grab('title'),
        status: grab('status'),
        vForm: grab('vForm'), vCine: grab('vCine'), vFog: grab('vFog'),
      };
      window.__probe = info;
    } catch (e) {
      window.__probe = { ok: false, err: String(e && e.stack || e) };
    }
  }, 10000);
})();
</script>
```

Note: `r.camera` — the renderer doesn't hold a reference to the camera... actually THREE.WebGLRenderer does not store the camera. Right, `renderer.camera` doesn't exist. Skip the camera position — just r.info will do. In fact, info.render.calls/points/tris after 10 seconds is a great signal (should be several hundred).

Wait — about the status: the innerText of my #status element contains #statusLines and .cur. OK.

