- pick the target with type 'page'
- ws = new WebSocket(t.webSocketDebuggerUrl)
- send {id:1, method:'Page.enable'}, {id:2, method:'Runtime.enable'}, {id:3, method:'Log.enable'}, {id:4, method:'Page.navigate', params:{url}}
